import { ArrowDownToLine, ArrowLeft, BadgeCheck, CalendarDays, Check, CheckCircle2, ChevronLeft, CircleAlert, Clock3, FileCheck2, FileSpreadsheet, FileText, Gift, IdCard, Info, LoaderCircle, Pencil, Plus, Printer, ShieldCheck, Sparkles, Trash2, UploadCloud, Users, Wallet, Waves, X } from "lucide-react";
