function ImportForm({ initialMonth, close }: { initialMonth?: string; close: () => void }) {
  const { refresh, notify, navigate } = useWorkspace(); const [month, setMonth] = useState(initialMonth || getPeriod()); const [file, setFile] = useState<File | null>(null); const [dragging, setDragging] = useState(false); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const [result, setResult] = useState<number | null>(null); const input = useRef<HTMLInputElement>(null);
  function selectFile(candidate?: File) { setError(""); if (!candidate) return; if (!candidate.name.toLowerCase().endsWith(".xlsx")) { setError("فقط فایل با پسوند .xlsx انتخاب کنید."); return; } if (candidate.size > 5 * 1024 * 1024) { setError("حجم فایل نباید بیشتر از ۵ مگابایت باشد."); return; } setFile(candidate); }
  async function submit(e: FormEvent) { e.preventDefault(); if (!file) { setError("ابتدا فایل کارکرد را انتخاب کنید."); return; } setLoading(true); setError(""); try { const form = new FormData(); form.append("file", file); form.append("month", month); const response = await fetch("/api/payroll/import", { method: "POST", body: form }); const json = await response.json(); if (!response.ok) throw new Error(json.error); await refresh(); setResult(json.count); notify(`${fa(json.count)} فیش حقوقی محاسبه و ذخیره شد.`); } catch (e) { setError(e instanceof Error ? e.message : "بارگذاری انجام نشد."); } finally { setLoading(false); } }
  if (result !== null) return <><div className="import-success"><div><CheckCircle2 size={40} /></div><h2>کارکردها با موفقیت ثبت شدند</h2><p>{fa(result)} فیش حقوقی برای {periodLabel(month)} محاسبه و به‌صورت پیش‌نویس ذخیره شد.</p><div className="badge green"><ShieldCheck size={14} />اطلاعات در پایگاه داده ذخیره شد</div></div><div className="modal-footer"><button className="btn secondary" onClick={close}>بستن</button><button className="btn primary" onClick={() => { close(); navigate("payroll"); }}>مشاهده فیش‌های حقوقی<ArrowLeft size={16} /></button></div></>;
  return <form onSubmit={submit}><div className="modal-body"><Field label="دوره کارکرد"><PeriodSelect value={month} onChange={setMonth} /></Field><a className="template-download" href={`/api/export?type=template&month=${month}`}><span><FileSpreadsheet size={24} /><span><strong>۱. فایل الگوی کارکرد را دریافت کنید</strong><small>شامل ستون‌های استاندارد و چند ردیف نمونه</small></span></span><ArrowDownToLine size={19} /></a><div className="upload-title"><strong>۲. فایل تکمیل‌شده را بارگذاری کنید</strong><small>XLSX · حداکثر ۵ مگابایت</small></div><input type="file" ref={input} accept=".xlsx" className="hidden-file-input" onChange={e => selectFile(e.target.files?.[0])} />{file ? <div className="selected-file"><span className="file-excel-icon"><FileSpreadsheet size={29} /></span><div><strong dir="ltr">{file.name}</strong><small>{fa(Math.max(1, Math.round(file.size / 1024)))} کیلوبایت · آماده پردازش</small></div><button type="button" className="icon-button" aria-label="حذف فایل انتخاب‌شده" disabled={loading} onClick={() => { setFile(null); if (input.current) input.current.value = ""; }}><X size={17} /></button></div> : <button type="button" className={`upload-zone ${dragging ? "dragging" : ""}`} onClick={() => input.current?.click()} onDragOver={e => { e.preventDefault(); setDragging(true); }} onDragLeave={() => setDragging(false)} onDrop={e => { e.preventDefault(); setDragging(false); selectFile(e.dataTransfer.files[0]); }}><span><UploadCloud size={29} strokeWidth={1.5} /></span><strong>فایل اکسل را اینجا رها کنید</strong><p>یا برای انتخاب فایل <b>کلیک کنید</b></p><small>حداکثر ۱۰۰۰ ردیف در هر بارگذاری</small></button>}<div className="import-columns"><span>ستون‌های مورد نیاز:</span><div dir="ltr">{["code", "workDays", "overtimeHours", "fridayHours", "nightHours", "missionAllowance", "bonus", "deductions"].map(c => <code key={c}>{c}</code>)}</div></div>{error && <div className="inline-error"><CircleAlert size={17} />{error}</div>}<div className="inline-info"><ShieldCheck size={17} />حق تأهل، حق اولاد و کسر قسط مساعده به‌صورت خودکار از پرونده هر کارمند محاسبه می‌شود. تمام ردیف‌ها پیش از ذخیره بررسی می‌شوند. فیش‌های پرداخت‌شده قابل بازنویسی نیستند.</div>{loading && <div className="import-progress"><span /><p>در حال بررسی ردیف‌ها و محاسبه حقوق...</p></div>}</div><div className="modal-footer"><button type="button" className="btn secondary" disabled={loading} onClick={close}>انصراف</button><button className="btn primary" disabled={loading || !file} type="submit">{loading ? <LoaderCircle size={17} className="spin" /> : <FileCheck2 size={17} />}{loading ? "در حال پردازش..." : "بررسی، محاسبه و ثبت"}</button></div></form>;
}

function Payslip({ payroll: original, close }: { payroll: Payroll; close: () => void }) {
  const { data } = useWorkspace(); const payroll = data.payrolls.find(p => p.id === original.id) || original; const employee = data.employees.find(e => e.id === payroll.employeeId); const gross = payroll.baseSalary + payroll.overtimePay + payroll.fridayPay + payroll.nightPay + payroll.missionAllowance + payroll.bonus + payroll.maritalAllowance + payroll.childAllowance; const deductionsTotal = payroll.insurance + payroll.tax + payroll.deductions + payroll.advanceDeduction;
  const earningRows = [["حقوق پایه کارکرد", payroll.baseSalary], ["اضافه‌کاری", payroll.overtimePay], ...(payroll.fridayPay ? [["جمعه‌کاری", payroll.fridayPay]] : []), ...(payroll.nightPay ? [["شب‌کاری", payroll.nightPay]] : []), ...(payroll.missionAllowance ? [["حق مأموریت", payroll.missionAllowance]] : []), ...(payroll.maritalAllowance ? [["حق تأهل", payroll.maritalAllowance]] : []), ...(payroll.childAllowance ? [["حق اولاد", payroll.childAllowance]] : []), ["مزایا و پاداش", payroll.bonus]] as [string, number][];
  const deductionRows = [["بیمه سهم کارمند", payroll.insurance], ["مالیات حقوق", payroll.tax], ["سایر کسورات", payroll.deductions], ...(payroll.advanceDeduction ? [["قسط مساعده", payroll.advanceDeduction]] : [])] as [string, number][];
  return <><div className="payslip-wrap"><article className="payslip print-document"><header className="payslip-header"><div className="payslip-brand"><Waves size={34} /><div><strong>آبان</strong><small>{data.settings.companyName}</small></div></div><div><h2>فیش حقوقی</h2><p>{periodLabel(payroll.month)}</p></div><span className={`badge ${payroll.status === "paid" ? "green" : "amber"}`}><i />{payroll.status === "paid" ? "پرداخت شده" : "پیش‌نویس"}</span></header><div className="payslip-identity"><Detail label="نام و نام خانوادگی" value={employee?.name || "—"} /><Detail label="کد پرسنلی" value={fa(employee?.code || 0)} /><Detail label="واحد سازمانی" value={employee?.department || "—"} /><Detail label="عنوان شغلی" value={employee?.position || "—"} /><Detail label="روزهای کارکرد" value={`${fa(payroll.workDays)} روز`} /><Detail label="اضافه‌کاری" value={`${fa(payroll.overtimeHours)} ساعت`} /></div><div className="payslip-tables"><table><thead><tr><th>حقوق و مزایا</th><th>مبلغ (تومان)</th></tr></thead><tbody>{earningRows.map(([label, value]) => <tr key={label}><td>{label}</td><td>{fa(value)}</td></tr>)}</tbody><tfoot><tr><td>جمع حقوق و مزایا</td><td>{fa(gross)}</td></tr></tfoot></table><table><thead><tr><th>کسورات</th><th>مبلغ (تومان)</th></tr></thead><tbody>{deductionRows.map(([label, value]) => <tr key={label}><td>{label}</td><td>{fa(value)}</td></tr>)}</tbody><tfoot><tr><td>جمع کسورات</td><td>{fa(deductionsTotal)}</td></tr></tfoot></table></div><div className="payslip-net"><div><Wallet size={23} /><span>خالص قابل پرداخت</span></div><strong>{fa(payroll.netPay)} <small>تومان</small></strong></div><div className="payslip-insurance"><ShieldCheck size={15} /><span>بیمه سهم کارفرما (خارج از کسورات کارمند): <strong>{money(payroll.employerInsurance)}</strong></span></div><div className="payslip-signatures"><div><span>مدیریت مجموعه</span><i /></div><div><span>واحد مالی</span><i /></div><div><span>امضای دریافت‌کننده</span><i /></div></div><footer className="payslip-bottom"><span>صادرشده توسط سامانه مدیریت سرمایه انسانی آبان</span><span>شناسه: <b dir="ltr">{payroll.id.slice(0, 8).toUpperCase()}</b></span></footer></article></div><div className="modal-footer no-print"><button className="btn secondary" onClick={close}>بستن</button><button className="btn primary" onClick={() => window.print()}><Printer size={17} />چاپ / ذخیره PDF</button></div></>;
}

function Confirmation({ close }: { close: () => void }) {
  const { modal, mutate, busy } = useWorkspace(); if (modal?.type !== "confirm") return null; const danger = modal.action.endsWith("delete");
  async function submit() { if (modal?.type === "confirm" && await mutate(modal.action, modal.payload, danger ? "مورد انتخاب‌شده حذف شد." : "عملیات با موفقیت ثبت شد.")) close(); }
  return <><div className="confirmation-body"><div className={`confirmation-icon ${danger ? "danger" : ""}`}>{danger ? <Trash2 size={28} /> : <CheckCircle2 size={28} />}</div><p>{modal.description}</p>{danger && <small>لطفاً پیش از ادامه از تصمیم خود مطمئن شوید.</small>}</div><div className="modal-footer"><button className="btn secondary" disabled={busy} onClick={close}>انصراف</button><button className={`btn ${danger ? "danger" : "primary"}`} disabled={busy} onClick={submit}>{busy ? <LoaderCircle className="spin" size={16} /> : danger ? <Trash2 size={16} /> : <Check size={16} />}{danger ? "بله، حذف شود" : "تأیید و ثبت"}</button></div></>;
}

function HelpContent({ close }: { close: () => void }) {
  const { data, navigate } = useWorkspace(); const [open, setOpen] = useState<number | null>(0); const items = [
    { question: "چگونه حساب کارمندی ایجاد کنم؟", answer: "در مدیریت کارکنان، «افزودن کارمند» را انتخاب کنید. اطلاعات فردی، خانوادگی، مدارک هویتی، شغلی، ایمیل و رمز اولیه را وارد کنید. با ذخیره پرونده، حساب ورود کارمند نیز ایجاد می‌شود. برای متقاضیان استخدام، وضعیت «متقاضی استخدام» را انتخاب و پس از بررسی، استخدام را تأیید کنید." },
    { question: "درخواست‌های مرخصی چگونه تأیید می‌شوند؟", answer: "کارمند درخواست را ثبت می‌کند. مدیر همان واحد در مرحله اول و مدیر سیستم به نمایندگی منابع انسانی در مرحله دوم آن را بررسی می‌کنند. با تأیید نهایی، مانده مرخصی کم می‌شود. مراحل از تنظیمات قابل تغییر هستند." },
    { question: "امکانات رفاهی و پرداخت مساعده چگونه کار می‌کند؟", answer: "هر امکان رفاهی (مانند بلیت استخر یا بن رستوران) سقف ماهانه مستقل خود را دارد و از تنظیمات سیستم تعریف می‌شود. مساعده پس از تأیید مدیر واحد و مدیریت، به خزانه‌داری می‌رسد و می‌تواند یکجا یا طی چند ماه از حقوق کسر شود." },
    { question: "برای محاسبه حقوق چه فایلی بارگذاری کنم؟", answer: "از حقوق و دستمزد، «ورود کارکرد از اکسل» را انتخاب کنید. فایل الگو را دریافت و ستون‌های کد پرسنلی، روز کارکرد، اضافه‌کاری، جمعه‌کاری، شب‌کاری، حق مأموریت، مزایا و کسورات را تکمیل کنید. حق تأهل، حق اولاد و کسر قسط مساعده به‌صورت خودکار محاسبه می‌شوند." },
    { question: "چگونه نقش‌های مختلف را امتحان کنم؟", answer: "روی تصویر حساب در بالای صفحه کلیک کنید و یکی از حساب‌های نمایشی مدیر سیستم، مدیر واحد، مدیر مالی یا کارمند را انتخاب کنید. هر نقش دسترسی مخصوص خود را دارد. همه داده‌های این فضای نمایشی نمونه و قابل آزمایش هستند." }
  ];
  return <><div className="modal-body"><div className="help-welcome"><span><Waves size={33} /></span><div><h2>مدیریت روان، تیمی همراه</h2><p>از پرونده پرسنلی تا فیش حقوقی، همه‌چیز در یک فضای یکپارچه.</p></div></div><div className="help-accordion">{items.map((item, i) => <div key={item.question} className={open === i ? "open" : ""}><button aria-expanded={open === i} onClick={() => setOpen(open === i ? null : i)}><span>{fa(i + 1)}</span><strong>{item.question}</strong><Plus size={17} /></button>{open === i && <p>{item.answer}</p>}</div>)}</div><div className="inline-info"><ShieldCheck size={18} />این محیط با ۱۰۰۰ پرونده نمونه راه‌اندازی شده است. اطلاعات واقعی کارکنان را فقط در فضای عملیاتی و با سیاست دسترسی مناسب وارد کنید.</div></div><div className="modal-footer"><button className="btn secondary" onClick={close}>متوجه شدم</button><button className="btn primary" onClick={() => { close(); navigate(data.user.role === "admin" ? "employees" : "leave"); }}>شروع کنیم<ArrowLeft size={16} /></button></div></>;
}
