"use client";
import { useEffect, useState, type FormEvent } from "react";
import { ArrowDownToLine, ArrowLeft, ArrowUpLeft, BadgeCheck, BriefcaseBusiness, CalendarCheck2, CalendarDays, Check, CheckCircle2, ChevronLeft, CircleDollarSign, CircleHelp, Clock3, Download, Eye, FileCheck2, FileSpreadsheet, FileText, Filter, Gift, HeartHandshake, Info, LockKeyhole, Pencil, Plus, Printer, Search, Settings2, ShieldCheck, SlidersHorizontal, Trash2, Upload, Users, Wallet, X, XCircle } from "lucide-react";
import { useWorkspace } from "@/components/workspace-context";
import { Avatar, EmployeeBadge, EmptyState, Field, PageHeading, Pagination, PeriodSelect, StatusBadge, SubmitButton } from "@/components/ui";
import { dateFa, departments, fa, getPeriod, maritalStatusLabels, money, pageLabels, periodLabel, repaymentLabel, requestLabels, roleLabels, type AmenityConfig, type Employee, type Payroll, type Request, type Settings } from "@/lib/types";

export function EmployeesPage({ recruitment = false }: { recruitment?: boolean }) {
  const { data, search, setModal, mutate, busy } = useWorkspace(); const [query, setQuery] = useState(""); const [department, setDepartment] = useState("all"); const [status, setStatus] = useState("all"); const [page, setPage] = useState(1); const admin = data.user.role === "admin";
  const source = recruitment ? data.employees.filter(e => e.status === "candidate") : data.employees;
  const filtered = source.filter(e => (!query && !search || `${e.name} ${e.code} ${e.email} ${e.position}`.toLowerCase().includes((query || search).toLowerCase())) && (department === "all" || e.department === department) && (status === "all" || e.status === status));
  useEffect(() => setPage(1), [query, search, department, status, recruitment]);
  const currentPage = Math.min(page, Math.max(1, Math.ceil(filtered.length / 10))); const rows = filtered.slice((currentPage - 1) * 10, currentPage * 10);
  return <div className="page-enter"><PageHeading title={recruitment ? "جذب و استخدام" : "مدیریت کارکنان"} subtitle={recruitment ? "از اولین آشنایی تا اولین روز همکاری؛ مسیر جذب استعدادها در آبان." : "همه همکاران، یک تیم. پرونده‌های پرسنلی را از اینجا مدیریت کنید."}><a href="/api/export?type=employees" className="btn secondary"><Download size={16} />خروجی اکسل</a>{admin && <button className="btn primary" onClick={() => setModal({ type: "employee", candidate: recruitment })}><Plus size={17} />{recruitment ? "افزودن متقاضی" : "افزودن کارمند"}</button>}</PageHeading>
    {recruitment && <div className="info-banner recruitment-banner"><span className="info-banner-icon"><BriefcaseBusiness size={28} /></span><div><h3>فصل تازه‌ای از همکاری در آبان</h3><p>{fa(source.length)} متقاضی در مسیر پیوستن به تیم ما هستند. پس از بررسی پرونده، استخدام را تأیید کنید.</p></div><span className="badge green">جذب استعدادهای تازه</span></div>}
    <div className="mini-stats-grid"><MiniStat label={recruitment ? "متقاضیان در حال بررسی" : "همه کارکنان"} value={source.length} icon={<Users size={21} />} color="teal" /><MiniStat label={recruitment ? "واحدهای در حال جذب" : "همکاران فعال"} value={recruitment ? new Set(source.map(e => e.department)).size : source.filter(e => e.status === "active").length} icon={<BadgeCheck size={21} />} color="blue" /><MiniStat label={recruitment ? "استخدام‌های این ماه" : "در مرخصی"} value={recruitment ? data.employees.filter(e => e.status === "active" && getPeriod(new Date(e.hireDate)) === getPeriod()).length : source.filter(e => e.status === "on_leave").length} icon={<CalendarDays size={21} />} color="orange" /></div>
    <section className="card resource-card"><div className="resource-top"><div className="title-inline"><h2>{recruitment ? "پرونده متقاضیان" : "فهرست کارکنان"}</h2><span className="count-pill">{fa(source.length)} نفر</span></div>{!recruitment && <div className="tabs">{[{ id: "all", label: "همه" }, { id: "active", label: "فعال" }, { id: "on_leave", label: "در مرخصی" }, { id: "inactive", label: "غیرفعال" }].map(tab => <button key={tab.id} className={status === tab.id ? "active" : ""} onClick={() => setStatus(tab.id)}>{tab.label}</button>)}</div>}</div><div className="table-toolbar"><div className="input-search"><Search size={17} /><input placeholder="جستجوی نام، کد پرسنلی یا عنوان شغلی..." value={query} onChange={e => setQuery(e.target.value)} aria-label="جستجوی کارکنان" />{query && <button onClick={() => setQuery("")} aria-label="پاک کردن جستجو"><X size={14} /></button>}</div><div className="filter-select"><Filter size={15} /><select value={department} onChange={e => setDepartment(e.target.value)} aria-label="فیلتر واحد سازمانی"><option value="all">همه واحدها</option>{departments.map(d => <option key={d}>{d}</option>)}</select></div><span className="results-count">{fa(filtered.length)} نتیجه</span></div>
      {rows.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>کارمند</th><th>کد پرسنلی</th><th>واحد سازمانی</th><th>تاریخ {recruitment ? "ثبت پرونده" : "استخدام"}</th><th>وضعیت</th><th className="actions-heading">عملیات</th></tr></thead><tbody>{rows.map(e => <tr key={e.id}><td><button className="person-cell person-button" onClick={() => setModal({ type: "employee-detail", employee: e })}><Avatar employee={e} /><span><strong>{e.name}</strong><small>{e.position}</small></span></button></td><td><span className="employee-code">AB-{fa(e.code)}</span></td><td>{e.department}</td><td className="muted">{dateFa(e.hireDate)}</td><td><EmployeeBadge status={e.status} /></td><td><div className="row-actions"><button className="icon-button" title="مشاهده پروفایل" aria-label={`پروفایل ${e.name}`} onClick={() => setModal({ type: "employee-detail", employee: e })}><Eye size={16} /></button>{admin && <><button className="icon-button" title="ویرایش" aria-label={`ویرایش ${e.name}`} onClick={() => setModal({ type: "employee", employee: e })}><Pencil size={15} /></button>{recruitment ? <button className="btn small soft" disabled={busy} onClick={() => setModal({ type: "confirm", title: "تأیید استخدام", description: `آیا استخدام ${e.name} در واحد ${e.department} تأیید می‌شود؟ حساب کارمندی او فعال خواهد شد.`, action: "employee.save", payload: { ...e, status: "active" } })}><Check size={14} />استخدام</button> : null}<button className="icon-button danger-hover" title="حذف" aria-label={`حذف ${e.name}`} onClick={() => setModal({ type: "confirm", title: "حذف پرونده کارمند", description: `پرونده ${e.name} به همراه حساب کاربری، درخواست‌ها و سوابق حقوقی حذف می‌شود. این عملیات قابل بازگشت نیست.`, action: "employee.delete", payload: { id: e.id } })}><Trash2 size={15} /></button></>}</div></td></tr>)}</tbody></table></div> : <EmptyState title={query || department !== "all" ? "همکاری با این مشخصات پیدا نشد" : recruitment ? "برای یک همکاری تازه آماده‌ایم" : "اولین همکار را به آبان دعوت کنید"} description="می‌توانید فیلترها را تغییر دهید یا یک پرونده جدید بسازید." action={admin ? recruitment ? "افزودن متقاضی" : "افزودن کارمند" : undefined} onAction={() => setModal({ type: "employee", candidate: recruitment })} icon={Users} />}
      <Pagination page={currentPage} count={filtered.length} onChange={setPage} /></section><p className="page-footnote"><ShieldCheck size={14} />اطلاعات پرونده‌های پرسنلی و مدارک هویتی فقط در اختیار افراد دارای سطح دسترسی مجاز قرار می‌گیرد.</p></div>;
}

function MiniStat({ label, value, icon, color = "teal", unit = "نفر" }: { label: string; value: number | string; icon: React.ReactNode; color?: string; unit?: string }) { return <div className="mini-stat card"><span className={`mini-stat-icon ${color}`}>{icon}</span><div><p>{label}</p><strong>{typeof value === "number" ? fa(value) : value}<small>{unit}</small></strong></div></div>; }

export function RequestsPage({ type }: { type: string }) {
  const { data, search, setModal, navigate } = useWorkspace(); const [status, setStatus] = useState("all"); const [query, setQuery] = useState(""); const [department, setDepartment] = useState("all"); const [page, setPage] = useState(1); const personal = data.user.role === "employee"; const admin = data.user.role === "admin";
  const source = data.requests.filter(r => r.type === type); const filtered = source.filter(r => { const employee = data.employees.find(e => e.id === r.employeeId); return (status === "all" || r.status === status || status === "approved" && r.status === "paid") && (!query && !search || `${employee?.name} ${employee?.code} ${r.title}`.includes(query || search)) && (department === "all" || employee?.department === department); });
  useEffect(() => setPage(1), [status, query, search, department]); const current = Math.min(page, Math.max(1, Math.ceil(filtered.length / 10))); const rows = filtered.slice((current - 1) * 10, current * 10); const label = requestLabels[type]; const Icon = type === "leave" ? CalendarDays : type === "ticket" ? Gift : Wallet;
  return <div className="page-enter"><PageHeading title={type === "leave" ? "درخواست‌های مرخصی" : type === "ticket" ? "امکانات رفاهی" : "مساعده و تسهیلات"} subtitle={type === "leave" ? "تعادل کار و زندگی، با یک مسیر روشن برای درخواست و تأیید مرخصی." : type === "ticket" ? "سهمی از حال خوب آبان برای همکاران و خانواده‌هایشان." : "حمایت مالی از همکاران؛ شفاف از ثبت درخواست تا پرداخت خزانه‌داری."}><a href="/api/export?type=requests" className="btn secondary"><Download size={16} />خروجی اکسل</a><button className="btn primary" onClick={() => setModal({ type: "request", requestType: type })}><Plus size={17} />درخواست {label}</button></PageHeading>
    <div className={`info-banner ${type}-banner`}><span className="info-banner-icon"><Icon size={28} /></span><div><h3>{type === "leave" ? "هر درخواست، یک مسیر شفاف" : type === "ticket" ? `${fa(data.settings.amenities.length)} نوع امکان رفاهی با سقف ماهانه مستقل` : `سقف مساعده ماهانه: ${money(data.settings.advanceLimit)}`}</h3><p>{type === "leave" ? `ثبت توسط کارمند ← تأیید مدیر واحد${data.settings.leaveApprovalSteps === 2 ? " ← تأیید منابع انسانی" : ""}` : type === "ticket" ? "سهمیه هر امکان رفاهی مستقل و ماهانه است؛ درخواست‌های در انتظار نیز از سهمیه کسر می‌شوند." : "ثبت درخواست ← تأیید مدیر واحد ← تأیید مدیریت ← ثبت پرداخت خزانه‌داری؛ کسر یکجا یا اقساطی از حقوق"}</p></div>{admin && <button className="btn small secondary" onClick={() => navigate("settings")}><Settings2 size={14} />تنظیمات</button>}</div>
    <div className="mini-stats-grid four"><MiniStat label="همه درخواست‌ها" value={source.length} icon={<Icon size={21} />} unit="درخواست" /><MiniStat label="در انتظار بررسی" value={source.filter(r => r.status === "pending").length} icon={<Clock3 size={21} />} color="orange" unit="درخواست" /><MiniStat label={type === "advance" ? "پرداخت شده" : "تأیید شده"} value={source.filter(r => ["approved", "paid"].includes(r.status)).length} icon={<CheckCircle2 size={21} />} color="blue" unit="درخواست" /><MiniStat label="رد شده" value={source.filter(r => r.status === "rejected").length} icon={<XCircle size={21} />} color="purple" unit="درخواست" /></div>
    <section className="card resource-card"><div className="resource-top"><div className="title-inline"><h2>{personal ? "درخواست‌های من" : `فهرست درخواست‌های ${label}`}</h2><span className="count-pill">{fa(source.length)}</span></div><div className="tabs">{[{ id: "all", label: "همه" }, { id: "pending", label: "در انتظار" }, { id: "approved", label: type === "advance" ? "تأیید / پرداخت" : "تأیید شده" }, { id: "rejected", label: "رد شده" }].map(t => <button key={t.id} className={status === t.id ? "active" : ""} onClick={() => setStatus(t.id)}>{t.label}</button>)}</div></div><div className="table-toolbar"><div className="input-search"><Search size={17} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="جستجوی نام کارمند یا عنوان درخواست..." aria-label="جستجوی درخواست‌ها" /></div>{!personal && <div className="filter-select"><Filter size={15} /><select value={department} onChange={e => setDepartment(e.target.value)} aria-label="واحد سازمانی"><option value="all">همه واحدها</option>{departments.map(d => <option key={d}>{d}</option>)}</select></div>}<span className="results-count">{fa(filtered.length)} نتیجه</span></div>
      {rows.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>کارمند</th><th>عنوان درخواست</th><th>{type === "advance" ? "مبلغ / نحوه کسر" : type === "ticket" ? "تعداد" : "بازه مرخصی"}</th><th>تاریخ ثبت</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>{rows.map(r => { const e = data.employees.find(e => e.id === r.employeeId); return <tr key={r.id}><td><div className="person-cell"><Avatar employee={e} /><div><strong>{e?.name}</strong><small>{e?.department}</small></div></div></td><td><span className="table-title">{r.title}</span></td><td>{type === "advance" ? <><strong className="number-cell">{money(r.amount)}</strong><small className="muted">{repaymentLabel(r.repaymentMonths)}</small></> : type === "ticket" ? <span className="ticket-quantity"><Gift size={15} />{fa(r.quantity)} مورد</span> : <span className="date-range">{dateFa(r.startDate)}<small>تا {dateFa(r.endDate)}</small></span>}</td><td className="muted">{dateFa(r.createdAt)}</td><td><StatusBadge request={r} /></td><td><button className="btn small table-review" onClick={() => setModal({ type: "request-detail", request: r })}>{r.status === "pending" && !personal ? "بررسی" : "جزئیات"}<ChevronLeft size={14} /></button></td></tr>; })}</tbody></table></div> : <EmptyState title={status !== "all" || query ? "درخواستی با این فیلتر وجود ندارد" : "هنوز درخواستی ثبت نشده"} description="درخواست جدید خود را ثبت کنید؛ وضعیت هر مرحله را همین‌جا می‌بینید." action={`ثبت درخواست ${label}`} onAction={() => setModal({ type: "request", requestType: type })} icon={Icon} />}
      <Pagination page={current} count={filtered.length} onChange={setPage} /></section></div>;
}

export function PayrollPage() {
  const { data, search, setModal } = useWorkspace(); const [month, setMonth] = useState(getPeriod()); const [query, setQuery] = useState(""); const [status, setStatus] = useState("all"); const [page, setPage] = useState(1); const financial = ["admin", "finance"].includes(data.user.role);
  const source = data.payrolls.filter(p => p.month === month); const filtered = source.filter(p => { const e = data.employees.find(e => e.id === p.employeeId); return (status === "all" || p.status === status) && (!query && !search || `${e?.name} ${e?.code}`.includes(query || search)); });
  useEffect(() => setPage(1), [month, query, status, search]); const current = Math.min(page, Math.max(1, Math.ceil(filtered.length / 10))); const drafts = source.filter(p => p.status === "draft");
  const grossOf = (p: Payroll) => p.baseSalary + p.overtimePay + p.fridayPay + p.nightPay + p.missionAllowance + p.bonus + p.maritalAllowance + p.childAllowance;
  return <div className="page-enter"><PageHeading title={financial ? "حقوق و دستمزد" : "فیش‌های حقوقی من"} subtitle="محاسبه دقیق‌تر، پرداخت شفاف‌تر؛ همه اطلاعات حقوق در یک نگاه."><div className="period-control"><CalendarDays size={16} /><PeriodSelect value={month} onChange={setMonth} /></div>{financial && <><a className="btn secondary" href={`/api/export?type=payroll&month=${month}`}><Download size={16} />خروجی اکسل</a><button className="btn primary" onClick={() => setModal({ type: "import", month })}><Upload size={16} />ورود کارکرد از اکسل</button></>}</PageHeading>
    <div className="mini-stats-grid four"><MiniStat label="جمع خالص پرداختی" value={new Intl.NumberFormat("fa-IR", { maximumFractionDigits: 1 }).format(source.reduce((s, p) => s + p.netPay, 0) / 1000000)} unit="میلیون تومان" icon={<Wallet size={21} />} /><MiniStat label="بیمه کارکنان و کارفرما" value={new Intl.NumberFormat("fa-IR", { maximumFractionDigits: 1 }).format(source.reduce((s, p) => s + p.insurance + p.employerInsurance, 0) / 1000000)} unit="میلیون تومان" icon={<ShieldCheck size={21} />} color="blue" /><MiniStat label="کسر اقساط مساعده" value={new Intl.NumberFormat("fa-IR", { maximumFractionDigits: 1 }).format(source.reduce((s, p) => s + p.advanceDeduction, 0) / 1000000)} unit="میلیون تومان" icon={<CircleDollarSign size={21} />} color="purple" /><MiniStat label="در انتظار پرداخت" value={drafts.length} unit="فیش" icon={<Clock3 size={21} />} color="orange" /></div>
    <section className="card resource-card"><div className="resource-top"><div className="title-inline"><h2>فیش‌های {periodLabel(month)}</h2><span className="count-pill">{fa(source.length)} فیش</span></div>{financial && <button className="text-button" onClick={() => setModal({ type: "payroll", month })}><Plus size={16} />ثبت کارکرد دستی</button>}</div><div className="table-toolbar"><div className="input-search"><Search size={17} /><input placeholder="جستجوی نام یا کد پرسنلی..." value={query} onChange={e => setQuery(e.target.value)} aria-label="جستجوی فیش" /></div><select className="filter-native" aria-label="وضعیت پرداخت" value={status} onChange={e => setStatus(e.target.value)}><option value="all">همه وضعیت‌ها</option><option value="draft">پیش‌نویس</option><option value="paid">پرداخت شده</option></select>{financial && drafts.length > 0 && <button className="btn small soft toolbar-end" onClick={() => setModal({ type: "confirm", title: "ثبت پرداخت حقوق", description: `پرداخت ${fa(drafts.length)} فیش پیش‌نویس ماه ${periodLabel(month)} به مبلغ مجموع ${money(drafts.reduce((s, p) => s + p.netPay, 0))} ثبت شود؟ پس از ثبت پرداخت، این فیش‌ها قابل تغییر نیستند.`, action: "payroll.pay", payload: { month } })}><Check size={15} />ثبت پرداخت پیش‌نویس‌ها</button>}</div>
      {filtered.length ? <div className="table-scroll"><table className="data-table payroll-table"><thead><tr><th>کارمند</th><th>کارکرد</th><th>حقوق و مزایا</th><th>بیمه کارمند</th><th>خالص پرداختی <small>(تومان)</small></th><th>وضعیت</th><th>فیش حقوقی</th></tr></thead><tbody>{filtered.slice((current - 1) * 10, current * 10).map(p => { const e = data.employees.find(e => e.id === p.employeeId); return <tr key={p.id}><td><div className="person-cell"><Avatar employee={e} /><div><strong>{e?.name}</strong><small>کد پرسنلی {fa(e?.code || 0)}</small></div></div></td><td>{fa(p.workDays)} روز{(p.fridayHours > 0 || p.nightHours > 0) && <small className="muted"> · {p.fridayHours > 0 && `${fa(p.fridayHours)}س جمعه`}{p.fridayHours > 0 && p.nightHours > 0 && "، "}{p.nightHours > 0 && `${fa(p.nightHours)}س شب`}</small>}</td><td className="number-cell">{fa(grossOf(p))}</td><td className="number-cell muted">{fa(p.insurance)}</td><td className="number-cell net-pay">{fa(p.netPay)}</td><td><span className={`badge ${p.status === "paid" ? "green" : "amber"}`}><i />{p.status === "paid" ? "پرداخت شده" : "پیش‌نویس"}</span></td><td><div className="row-actions"><button className="icon-button" title="مشاهده و چاپ فیش" aria-label={`فیش حقوقی ${e?.name}`} onClick={() => setModal({ type: "payslip", payroll: p })}><Printer size={17} /></button>{financial && p.status === "draft" && <><button className="icon-button" title="ویرایش کارکرد" aria-label="ویرایش کارکرد" onClick={() => setModal({ type: "payroll", payroll: p })}><Pencil size={15} /></button><button className="icon-button danger-hover" aria-label="حذف پیش‌نویس" onClick={() => setModal({ type: "confirm", title: "حذف فیش پیش‌نویس", description: `فیش پیش‌نویس ${e?.name} برای ${periodLabel(p.month)} حذف شود؟`, action: "payroll.delete", payload: { id: p.id } })}><Trash2 size={15} /></button></>}</div></td></tr>; })}</tbody></table></div> : <EmptyState title="فیشی برای این ماه وجود ندارد" description={financial ? "فایل کارکرد را بارگذاری کنید تا حقوق، بیمه و مالیات به‌صورت خودکار محاسبه شوند." : "پس از ثبت کارکرد توسط واحد مالی، فیش شما اینجا نمایش داده می‌شود."} action={financial ? "ورود کارکرد از اکسل" : undefined} onAction={() => setModal({ type: "import" })} icon={FileSpreadsheet} />}
      <Pagination page={current} count={filtered.length} onChange={setPage} /></section><div className="calculation-note"><Info size={18} /><p>مبالغ به تومان است. حقوق بر اساس روزهای کارکرد، اضافه‌کاری، جمعه‌کاری و شب‌کاری با ضریب مربوطه، حق تأهل، حق اولاد، مزایا، بیمه، مالیات، سایر کسورات و کسر خودکار قسط مساعده محاسبه می‌شود. نرخ‌ها از تنظیمات مجموعه خوانده می‌شوند.</p></div></div>;
}

export function ReportsPage() {
  const { data, navigate } = useWorkspace(); const [month, setMonth] = useState(getPeriod()); const financial = ["admin", "finance"].includes(data.user.role); const monthRequests = data.requests.filter(r => r.month === month); const salaries = data.payrolls.filter(p => p.month === month); const approved = monthRequests.filter(r => ["approved", "paid"].includes(r.status)).length;
  return <div className="page-enter"><PageHeading title="گزارش‌ها و بینش‌ها" subtitle="تصویری روشن از سرمایه انسانی، رفاه کارکنان و عملکرد مالی مجموعه."><div className="period-control"><CalendarDays size={16} /><PeriodSelect value={month} onChange={setMonth} /></div><a className="btn primary" href="/api/export?type=report"><Download size={16} />دریافت گزارش جامع</a></PageHeading><div className="mini-stats-grid"><MiniStat label="تعداد کارکنان" value={data.employees.length} icon={<Users size={21} />} /><MiniStat label={`درخواست‌های ${periodLabel(month)}`} value={monthRequests.length} unit="درخواست" icon={<CalendarDays size={21} />} color="blue" /><MiniStat label="درصد درخواست‌های نهایی‌شده" value={fa(monthRequests.length ? Math.round(approved / monthRequests.length * 100) : 0)} unit="درصد" icon={<CheckCircle2 size={21} />} color="purple" /></div><div className="reports-grid"><section className="card report-departments"><div className="card-heading"><div><h2>سرمایه انسانی به تفکیک واحد</h2><p>توزیع فعلی همکاران در مجموعه</p></div><Users size={20} className="muted" /></div><div className="report-bars">{departments.map((d, i) => { const count = data.employees.filter(e => e.department === d).length; return <div key={d}><div><span>{d}</span><strong>{fa(count)} <small>نفر</small></strong></div><div className="bar-track"><span style={{ width: `${count / Math.max(1, data.employees.length) * 100}%`, background: ["#169e99", "#61bfb6", "#8fcac8", "#7aaec7", "#b6aad2", "#dbba84"][i] }} /></div></div>; })}</div><button className="text-button" onClick={() => navigate("employees")}>مشاهده جزئیات کارکنان<ArrowLeft size={14} /></button></section><section className="card report-summary"><div className="card-heading"><div><h2>خلاصه {periodLabel(month)}</h2><p>اعداد کلیدی برای تصمیم‌های بهتر</p></div><FileText size={20} className="muted" /></div><div className="summary-list"><div><span>درخواست‌های مرخصی</span><strong>{fa(monthRequests.filter(r => r.type === "leave").length)} درخواست</strong></div><div><span>درخواست‌های امکانات رفاهی تأییدشده</span><strong>{fa(monthRequests.filter(r => r.type === "ticket" && r.status === "approved").reduce((sum, r) => sum + r.quantity, 0))} مورد</strong></div><div><span>مساعده پرداخت‌شده</span><strong>{money(monthRequests.filter(r => r.type === "advance" && r.status === "paid").reduce((sum, r) => sum + r.amount, 0))}</strong></div>{financial && <><div><span>جمع خالص حقوق</span><strong>{money(salaries.reduce((sum, p) => sum + p.netPay, 0))}</strong></div><div><span>بیمه سهم کارفرما</span><strong>{money(salaries.reduce((sum, p) => sum + p.employerInsurance, 0))}</strong></div><div><span>حق تأهل و اولاد پرداختی</span><strong>{money(salaries.reduce((sum, p) => sum + p.maritalAllowance + p.childAllowance, 0))}</strong></div><div><span>مالیات حقوق</span><strong>{money(salaries.reduce((sum, p) => sum + p.tax, 0))}</strong></div></>}</div></section></div><h2 className="section-title">گزارش‌های قابل دریافت</h2><div className="report-downloads">{[{ title: "گزارش کارکنان", description: "مشخصات پرسنلی و واحدهای سازمانی", type: "employees", Icon: Users, color: "teal" }, { title: "گزارش درخواست‌ها", description: "مرخصی، امکانات رفاهی و گردش تأیید مساعده", type: "requests", Icon: CalendarDays, color: "blue" }, ...(financial ? [{ title: "گزارش حقوق و بیمه", description: "حقوق، کسورات و سهم بیمه هر کارمند", type: "payroll", Icon: FileSpreadsheet, color: "purple" }] : [])].map(({ title, description, type, Icon, color }) => <a className="card report-download" href={`/api/export?type=${type}&month=${month}`} key={type}><span className={`report-icon ${color}`}><Icon size={24} /></span><h3>{title}</h3><p>{description}</p><div><span>فایل Excel <small>.xlsx</small></span><ArrowDownToLine size={18} /></div></a>)}</div></div>;
}

export function SettingsPage() {
  const { data, mutate, busy } = useWorkspace(); const [form, setForm] = useState<Settings>({ ...data.settings, amenities: data.settings.amenities.map(a => ({ ...a })) });
  const update = (key: keyof Settings, value: string) => setForm(f => ({ ...f, [key]: key === "companyName" ? value : Number(value) } as Settings));
  const updateAmenity = (index: number, patch: Partial<AmenityConfig>) => setForm(f => ({ ...f, amenities: f.amenities.map((a, i) => i === index ? { ...a, ...patch } : a) }));
  const addAmenity = () => setForm(f => ({ ...f, amenities: [...f.amenities, { id: crypto.randomUUID(), title: "", monthlyLimit: 1 }] }));
  const removeAmenity = (index: number) => setForm(f => ({ ...f, amenities: f.amenities.filter((_, i) => i !== index) }));
  async function submit(event: FormEvent) { event.preventDefault(); await mutate("settings.save", { ...form }, "تنظیمات مجموعه با موفقیت به‌روزرسانی شد."); }
  return <div className="page-enter"><PageHeading title="تنظیمات سیستم" subtitle="قواعد سازمان خود را تعریف کنید؛ آبان مطابق مسیر شما حرکت می‌کند."><button className="btn secondary" onClick={() => setForm({ ...data.settings, amenities: data.settings.amenities.map(a => ({ ...a })) })}>بازگردانی تغییرات</button><button className="btn primary" type="submit" form="settings-form" disabled={busy}>{busy ? "در حال ذخیره..." : "ذخیره تنظیمات"}<Check size={17} /></button></PageHeading><form id="settings-form" onSubmit={submit} className="settings-layout">
    <section className="card settings-card"><div className="settings-section-title"><span className="settings-icon teal"><Settings2 size={22} /></span><div><h2>اطلاعات مجموعه</h2><p>نام و هویت فضای کاری شما</p></div></div><div className="form-grid"><Field label="نام مجموعه"><input required value={form.companyName} onChange={e => update("companyName", e.target.value)} /></Field><Field label="زبان و تقویم"><input value="فارسی · تقویم هجری شمسی" disabled /></Field></div></section>
    <section className="card settings-card"><div className="settings-section-title"><span className="settings-icon blue"><Gift size={22} /></span><div><h2>امکانات رفاهی کارکنان</h2><p>هر امکان، سقف درخواست ماهانه مستقل خود را دارد.</p></div></div><div className="amenity-list">{form.amenities.map((amenity, index) => <div className="amenity-row" key={amenity.id}><input required placeholder="عنوان امکان رفاهی" value={amenity.title} onChange={e => updateAmenity(index, { title: e.target.value })} /><div className="input-unit amenity-limit"><input required type="number" min={0} max={1000} value={amenity.monthlyLimit} onChange={e => updateAmenity(index, { monthlyLimit: Number(e.target.value) })} /><span>در ماه</span></div><button type="button" className="icon-button danger-hover" aria-label={`حذف ${amenity.title || "امکان رفاهی"}`} disabled={form.amenities.length <= 1} onClick={() => removeAmenity(index)}><Trash2 size={15} /></button></div>)}</div><button type="button" className="text-button" onClick={addAmenity}><Plus size={15} />افزودن امکان رفاهی</button><Field label="سقف مساعده ماهانه" hint="برای هر کارمند، یک درخواست مساعده فعال در هر ماه مجاز است." className="spaced-field"><div className="input-unit"><input required type="number" min="1" max="1000000000" value={form.advanceLimit} onChange={e => update("advanceLimit", e.target.value)} /><span>تومان</span></div></Field></section>
    <section className="card settings-card"><div className="settings-section-title"><span className="settings-icon orange"><CalendarCheck2 size={22} /></span><div><h2>گردش تأیید درخواست‌ها</h2><p>مسیر بررسی و مسئولیت هر مرحله</p></div></div><Field label="مراحل تأیید مرخصی"><select value={form.leaveApprovalSteps} onChange={e => update("leaveApprovalSteps", e.target.value)}><option value={1}>یک مرحله: مدیر واحد</option><option value={2}>دو مرحله: مدیر واحد + منابع انسانی</option></select></Field><div className="settings-workflow"><span><CheckCircle2 size={18} />ثبت کارمند</span><ChevronLeft size={17} /><span><Users size={18} />مدیر واحد</span>{form.leaveApprovalSteps === 2 && <><ChevronLeft size={17} /><span><ShieldCheck size={18} />منابع انسانی</span></>}</div><p className="field-note">مساعده همیشه به تأیید مدیر واحد، مدیریت و ثبت پرداخت واحد مالی نیاز دارد. امکانات رفاهی با تأیید مدیر واحد نهایی می‌شود.</p></section>
    <section className="card settings-card"><div className="settings-section-title"><span className="settings-icon purple"><HeartHandshake size={22} /></span><div><h2>حق تأهل و حق اولاد</h2><p>این مزایا به‌صورت خودکار در فیش حقوقی هر کارمند لحاظ می‌شود.</p></div></div><div className="form-grid"><Field label="حق تأهل (کارمندان متأهل)"><div className="input-unit"><input type="number" required min={0} value={form.maritalAllowance} onChange={e => update("maritalAllowance", e.target.value)} /><span>تومان</span></div></Field><Field label="حق اولاد (هر فرزند)"><div className="input-unit"><input type="number" required min={0} value={form.childAllowance} onChange={e => update("childAllowance", e.target.value)} /><span>تومان</span></div></Field><Field label="حداکثر فرزند مشمول"><div className="input-unit"><input type="number" required min={0} max={10} value={form.maxChildrenAllowance} onChange={e => update("maxChildrenAllowance", e.target.value)} /><span>فرزند</span></div></Field></div></section>
    <section className="card settings-card"><div className="settings-section-title"><span className="settings-icon purple"><Wallet size={22} /></span><div><h2>بیمه و مالیات حقوق</h2><p>نرخ‌های محاسبه فیش‌های جدید؛ سوابق قبلی تغییر نمی‌کنند.</p></div></div><div className="form-grid">{([{ key: "insurancePercent", label: "بیمه سهم کارمند", max: 100, unit: "درصد" }, { key: "employerInsurancePercent", label: "بیمه سهم کارفرما", max: 100, unit: "درصد" }, { key: "taxPercent", label: "نرخ مالیات مازاد بر معافیت", max: 100, unit: "درصد" }, { key: "taxExemption", label: "معافیت مالیاتی ماهانه", max: 1000000000, unit: "تومان" }] as const).map(({ key, label, max, unit }) => <Field key={key} label={label}><div className="input-unit"><input type="number" required min="0" max={max} value={form[key]} onChange={e => update(key, e.target.value)} /><span>{unit}</span></div></Field>)}</div><div className="calculation-note"><Info size={18} /><p>این نرخ‌ها نمونه و قابل تنظیم هستند. واحد مالی باید پیش از استفاده عملیاتی، محاسبات را با مقررات جاری بیمه و مالیات تطبیق دهد.</p></div></section></form></div>;
}

export function ProfilePage() {
  const { data, mutate, busy } = useWorkspace(); const employee = data.employees.find(e => e.id === data.user.employeeId); const [name, setName] = useState(data.user.name); const [phone, setPhone] = useState(employee?.phone || ""); const [changePassword, setChangePassword] = useState(false); const [currentPassword, setCurrentPassword] = useState(""); const [password, setPassword] = useState("");
  async function submit(event: FormEvent) { event.preventDefault(); if (await mutate("profile.save", { name, phone, ...(changePassword ? { currentPassword, password } : {}) }, "پروفایل شما به‌روزرسانی شد.")) { setCurrentPassword(""); setPassword(""); setChangePassword(false); } }
  return <div className="page-enter"><PageHeading title="پروفایل و دسترسی" subtitle="اطلاعات شخصی، نقش سازمانی و امنیت حساب شما در آبان." /><div className="profile-layout"><section className="card profile-overview"><div className="profile-cover"><span /><span /><span /></div><Avatar employee={employee} name={data.user.name} image={data.user.role === "admin" ? "/images/admin.jpg" : undefined} size="large" /><h2>{data.user.name}</h2><span className="badge green"><ShieldCheck size={12} />{roleLabels[data.user.role]}</span><p className="profile-email" dir="ltr">{data.user.email}</p><div className="profile-facts"><div><span>مجموعه</span><strong>{data.settings.companyName}</strong></div><div><span>واحد سازمانی</span><strong>{employee?.department || "مدیریت مجموعه"}</strong></div><div><span>کد پرسنلی</span><strong>{employee ? fa(employee.code) : "مدیریت سیستم"}</strong></div><div><span>تاریخ همکاری</span><strong>{employee ? dateFa(employee.hireDate) : "—"}</strong></div>{employee && <div><span>مانده مرخصی</span><strong>{fa(employee.leaveBalance)} روز</strong></div>}{employee && <div><span>وضعیت تأهل</span><strong>{maritalStatusLabels[employee.maritalStatus]}{employee.childrenCount > 0 ? ` · ${fa(employee.childrenCount)} فرزند` : ""}</strong></div>}</div></section><section className="card profile-form"><div className="card-heading"><h2>اطلاعات حساب کاربری</h2><Pencil size={18} className="muted" /></div><form onSubmit={submit}><div className="form-grid"><Field label="نام و نام خانوادگی"><input required value={name} onChange={e => setName(e.target.value)} /></Field><Field label="نشانی ایمیل" hint="ایمیل فقط توسط مدیر سیستم تغییر می‌کند."><input value={data.user.email} disabled dir="ltr" /></Field>{employee && <Field label="شماره تماس"><input value={phone} onChange={e => setPhone(e.target.value)} dir="ltr" /></Field>}<Field label="سطح دسترسی"><input value={roleLabels[data.user.role]} disabled /></Field></div><button className="password-toggle" type="button" onClick={() => setChangePassword(!changePassword)}><LockKeyhole size={17} />تغییر رمز عبور<ChevronLeft size={16} className={changePassword ? "rotate-down" : ""} /></button>{changePassword && <div className="form-grid password-fields"><Field label="رمز عبور فعلی"><input required type="password" autoComplete="current-password" value={currentPassword} onChange={e => setCurrentPassword(e.target.value)} dir="ltr" /></Field><Field label="رمز عبور جدید" hint="حداقل ۸ نویسه"><input required minLength={8} type="password" autoComplete="new-password" value={password} onChange={e => setPassword(e.target.value)} dir="ltr" /></Field></div>}<div className="form-footer"><SubmitButton busy={busy} /></div></form><div className="security-note"><ShieldCheck size={22} /><div><strong>امنیت، بخشی از تجربه آبان است</strong><p>رمز شما رمزنگاری‌شده ذخیره می‌شود و نشست ورود پس از ۷ روز منقضی خواهد شد.</p></div></div></section></div></div>;
}
